security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['scheduleOperations']['enabled']: 
		canCreate = True
		canEdit = True if len(value['data'] or []) > 0 else False

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}

def buildElement(value, fontWeight, bgColor):

	style = {}
	if fontWeight is not None:	style.update({"fontWeight": fontWeight})	
	if bgColor is not None:
		style.update({"backgroundColor": bgColor})	
		style.update({"color": bgColorDict[bgColor]})
		style.update({"borderBottomRightRadius": '5px'})
		style.update({"borderTopLeftRadius": '5px'})
		style.update({"borderTopRightRadius": '5px'})
		style.update({"borderBottomLeftRadius": '5px'})
		style.update({"margin": '4px'})

	return {"value": value, "style":style}

self.view.custom.info = {"showBar": True, "text": "Formatting records", "type": "INFO"}	

data = system.kanoa.utilities.convertDatasetToJSON(value)

bgColors = []
for row in data:
	bgColors.append(row['statusColor'])
	bgColors.append(row['itemColor'] or row['itemClassColor'])
	bgColors.append(row['modeColor'])

bgColors = list(set(bgColors))
bgColorDict = {}
for bgColor in bgColors:
	bgColorDict[bgColor] = system.kanoa.utilities.getContrastingColor(bgColor)

for row in data:
	row['workOrderStatusName'] = buildElement(row['workOrderStatusName'], None, row['statusColor'])
	row['itemName'] = buildElement(row['itemName'], None, row['itemColor'] or row['itemClassColor'])
	row['modeName'] = buildElement(row['modeName'], None, row['modeColor'])
	row['lastUpdated'] = row['changedDate'] or row['createdDate']

self.view.custom.info = {"showBar": False, "text": "", "type": "INFO"}	

return data

