customMethods.script:
for item in self.view.custom.table.selection.data:
	retVal, msg = system.kanoa.order.deleteProductionOrder(item['workOrderId'], self.view.custom.security.userId)
	if retVal: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Order has been deleted.'})
	else: 
		system.perspective.sendMessage('showWarningToast', {'message': 'This order has been used in production and cannot be deleted. %s'%msg})
		import time
		time.sleep(0.5)

self.getWOData()

return


self.view.custom.info = {"showBar": True, "text": "Getting Orders", "type": "INFO"}		
filters = self.view.custom.filter

paramsDict = {'isActive': True} if filters['showActive'] else {'isActive': False, 'startDate': filters['startDate'], 'endDate': filters['endDate']}	
itemIdList = [item['itemId'] for item in system.kanoa.item.getAssetItems({'assetPath': filters['assetPath'] + '%'})] if filters['assetPath'] is not None else []
if len(itemIdList) > 0: paramsDict['itemIdList'] = itemIdList

if filters['showActual']: 
	paramsDict['ignoreActualQty'] = False
	if filters['showActive']:
		paramsDict['startDate'] = system.date.addYears(system.date.now(), -5)
		paramsDict['endDate'] = system.date.addYears(system.date.now(), 1)
else:
	paramsDict['ignoreActualQty'] = True

system.perspective.print("Calling getProductionOrders() with %s"%paramsDict)
data = system.kanoa.order.getProductionOrders(paramsDict)
self.view.custom.table.data = system.dataset.sort(data, 'workOrderId', False)

return

